class Solution:
    def findMaxAverage(self, nums: list[int], k: int) -> float:
        n = len(nums)
        if n <= k:
            return sum(nums) / k

        curSum = sum(nums[:k])
        best = curSum
        for i in range(k, n):
            curSum += nums[i] - nums[i - k]
            best = max(curSum, best)

        return best / k
